function relativeCvDate(value:string){const date=new Date(value);if(Number.isNaN(date.getTime()))return "Date unavailable";const days=Math.max(0,Math.floor((Date.now()-date.getTime())/86400000));if(days===0)return "Edited today";if(days===1)return "Edited yesterday";if(days<7)return "Edited "+days+" days ago";return "Edited "+new Intl.DateTimeFormat("en-NG",{day:"numeric",month:"short",year:"numeric"}).format(date);}
const CV_HEADINGS=["EXPERIENCE","WORK HISTORY","EMPLOYMENT","EDUCATION","ACADEMIC BACKGROUND","SKILLS","TECHNICAL SKILLS","ABOUT","SUMMARY","PROFILE","PROJECTS","CERTIFICATIONS","CERTIFICATION","LANGUAGES","AWARDS","VOLUNTEER","REFERENCES","HOBBIES","INTERESTS","NYSC","NYSC EXPERIENCE"];
function cvSection(text:string,names:string[]){const lines=text.split("\n"),start=lines.findIndex(line=>names.some(name=>new RegExp("^\\s*"+name+"\\s*:?\\s*$","i").test(line.trim())));if(start<0)return "";let end=lines.length;for(let i=start+1;i<lines.length;i++){if(CV_HEADINGS.some(name=>new RegExp("^\\s*"+name+"\\s*:?\\s*$","i").test(lines[i].trim()))){end=i;break;}}return lines.slice(start+1,end).join("\n").trim();}
function parseCVText(input:string):ParsedCv{
 const text=input.trim().replace(/\r/g,""),first=text.split("\n")[0]?.trim()||"",email=text.match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i)?.[0]||"",phone=text.match(/(?:\+?234|0)[789][01]\d{8}/)?.[0]||"";
 const words=first.split(/\s+/),nameValid=words.length>=2&&words.length<=4&&first.length<40&&!first.includes("@")&&!/\d/.test(first)&&!/(EXPERIENCE|EDUCATION|SKILLS)/i.test(first);
 const aboutMe=cvSection(text,["ABOUT","SUMMARY","PROFILE","PROFESSIONAL SUMMARY"]),expText=cvSection(text,["EXPERIENCE","WORK HISTORY","EMPLOYMENT"]);
 const experience=expText.split(/\n\s*\n/).map(v=>v.trim()).filter(Boolean).map((chunk,index)=>{const lines=chunk.split("\n").map(v=>v.trim()).filter(Boolean),dateLine=lines.find(v=>/(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec|\d{4}).*[-–—].*(Present|Current|Now|\d{4})/i.test(v))||"",dateMatch=dateLine.match(/((?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)?\s*\d{4})\s*[-–—]\s*(Present|Current|Now|\d{4})/i),contentLines=lines.filter(v=>v!==dateLine);return {id:Date.now()+index,role:(contentLines[0]||"").slice(0,59),company:contentLines[1]||"",location:"",start:dateMatch?.[1]?.trim()||"",end:dateMatch?.[2]?.trim()||"",details:contentLines.slice(2).join("\n")};}).filter(v=>v.role||v.company||v.details);
 const eduText=cvSection(text,["EDUCATION","ACADEMIC BACKGROUND"]),education=eduText.split(/\n\s*\n/).map(v=>v.trim()).filter(Boolean).map((chunk,index)=>{const lines=chunk.split("\n").map(v=>v.trim()).filter(Boolean);return {id:Date.now()+100+index,qualification:lines[0]||"",school:lines[1]||"",year:chunk.match(/\b(?:19|20)\d{2}\b/)?.[0]||""};}).filter(v=>v.qualification||v.school);
 const skills=cvSection(text,["SKILLS","TECHNICAL SKILLS"]).split(/[,•\n]/).map(v=>v.trim()).filter(v=>v.length>1),projects=cvSection(text,["PROJECTS"]),customSections:CvCustomSection[]=[];
 for(const heading of ["CERTIFICATIONS","CERTIFICATION","LANGUAGES","AWARDS","VOLUNTEER","REFERENCES","HOBBIES","INTERESTS","NYSC","NYSC EXPERIENCE"]){const content=cvSection(text,[heading]);if(content)customSections.push({id:Date.now()+customSections.length,title:heading.charAt(0)+heading.slice(1).toLowerCase(),content});}
 const links=[...new Set(text.match(/(?:https?:\/\/|www\.)[^\s]+/gi)||[])];return {fullName:nameValid?first:"",email,phone,jobTitle:"",aboutMe,experience,education,skills,projects,customSections,links,languages:cvSection(text,["LANGUAGES"]),certifications:cvSection(text,["CERTIFICATIONS","CERTIFICATION"])};
}
