te(false),[customTitle,setCustomTitle]=useState(""),[customSuggestions,setCustomSuggestions]=useState<Record<number,string[]>>({}),[suggestionDrawerOpen,setSuggestionDrawerOpen]=useState(false),[previewOpen,setPreviewOpen]=useState(false);const cvFileRef=useRef<HTMLInputElement>(null);

 useEffect(()=>{const raw=localStorage.getItem("usekit-restore-cv")||localStorage.getItem("usekit-draft-cv");if(!raw)return;try{const p=JSON.parse(raw);const restoreId=localStorage.getItem("usekit-restore-id-cv")||p.editingDocId||"";setEditingDocId(restoreId);if(restoreId)localStorage.setItem("usekit-draft-cv",JSON.stringify({...p,editingDocId:restoreId}));localStorage.removeItem("usekit-restore-cv");localStorage.removeItem("usekit-restore-id-cv");setLayout(p.layout||"ats");setName(p.name||"");setTitle(p.title||"");setEmail(p.email||"");setPhone(p.phone||"");setLocation(p.location||"");setWebsite(p.website||"");setLinkedin(p.linkedin||"");setBehance(p.behance||"");setRole(p.role||"");setYears(p.years||"");setSummary(p.summary||"");setCareerObjective(p.careerObjective||"");setSkills(p.skills||"");setTools(p.tools||"");setSoft(p.soft||"");setLanguages(p.languages||"");setReference(p.reference||"");if(Array.isArray(p.work))setWork(p.work);if(Array.isArray(p.education))setEducation(p.education);setProjects(p.projects||"");setCertifications(p.certifications||"");setJob(p.job||"");setCustomSections(Array.isArray(p.customSections)?p.customSections:[]);setTargetRole(p.targetRole||"");localStorage.removeItem("usekit-restore-cv");setNotice("Saved CV restored. Continue editing.");}catch{setNotice("Could not restore the saved CV.");}},[]);
