 function applyCvData(p:Record<string,unknown>){setLayout(p.layout==="modern"?"modern":"ats");setName(String(p.name||p.fullName||""));setTitle(String(p.title||""));setEmail(String(p.email||""));setPhone(String(p.phone||""));setLocation(String(p.location||""));setWebsite(String(p.website||""));setLinkedin(String(p.linkedin||""));setBehance(String(p.behance||""));setRole(String(p.role||p.jobTitle||""));setYears(String(p.years||""));setSummary(String(p.summary||p.aboutMe||""));setCareerObjective(String(p.careerObjective||""));setSkills(Array.isArray(p.skills)?p.skills.join(", "):String(p.skills||""));setTools(String(p.tools||""));setSoft(String(p.soft||""));setLanguages(String(p.languages||""));setReference(String(p.reference||""));setWork(Array.isArray(p.work)&&p.work.length?p.work as Work[]:[{id:Date.now(),role:"",company:"",location:"",start:"",end:"Present",details:""}]);setEducation(Array.isArray(p.education)&&p.education.length?p.education as Edu[]:[{id:Date.now()+1,school:"",qualification:"",year:""}]);setProjects(String(p.projects||""));setCertifications(String(p.certifications||""));setJob(String(p.job||""));setCustomSections(Array.isArray(p.customSections)?p.customSections as CvCustomSection[]:[]);setTargetRole(String(p.targetRole||""));setEditingDocId(String(p.editingDocId||""));}
 function applyImportedCv(parsed:ParsedCv){setName(parsed.fullName);setTitle(parsed.jobTitle);setRole("");setYears("");setEmail(parsed.email);setPhone(parsed.phone);setLocation("");setWebsite(parsed.links.find(link=>!/linkedin|behance/i.test(link))||"");setLinkedin(parsed.links.find(link=>/linkedin/i.test(link))||"");setBehance(parsed.links.find(link=>/behance/i.test(link))||"");setCareerObjective("");setTools("");setSoft("");setReference("");setJob("");setSummary(parsed.aboutMe);setWork(parsed.experience.length?parsed.experience:[{id:Date.now(),role:"",company:"",location:"",start:"",end:"Present",details:""}]);setEducation(parsed.education.length?parsed.education:[{id:Date.now()+1,school:"",qualification:"",year:""}]);setSkills(parsed.skills.join(", "));setProjects(parsed.projects);setCustomSections(parsed.customSections);setLanguages(parsed.languages);setCertifications(parsed.certifications);setStep(0);setImportOpen(false);setAutoFillBanner(true);setHighlightAutoFill(true);window.scrollTo({top:0,behavior:"smooth"});window.setTimeout(()=>setHighlightAutoFill(false),3000);setNotice("Imported details are ready. Review every field before updating your CV.");}
 async function extractCvFile(file:File){setImportError("");setImportParsed(null);setRawCvText("");setPasteCvText("");if(file.size>5*1024*1024){setImportError("File too large (max 5MB), try smaller PDF or paste text below");return;}const lower=file.name.toLowerCase();if(!lower.endsWith(".pdf")&&!lower.endsWith(".docx")){setImportError("Please choose a PDF or DOCX file.");return;}setImportBusy(true);try{let extracted="";if(lower.endsWith(".pdf")){const pdfjs=await import("pdfjs-dist/legacy/build/pdf.mjs");pdfjs.GlobalWorkerOptions.workerSrc=new URL("pdfjs-dist/legacy/build/pdf.worker.min.mjs",import.meta.url).toString();const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false}).promise;const pages:string[]=[];try{for(let pageNum=1;pageNum<=pdf.numPages;pageNum++){const page=await pdf.getPage(pageNum);const content=await page.getTextContent();pages.push(content.items.map(item=>"str" in item?item.str:"").filter(Boolean).join(" "));page.cleanup();}}finally{await pdf.destroy();}extracted=pages.join("\n");}else{const mammoth=await import("mammoth");const result=await mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});extracted=result.value;}setRawCvText(extracted);if(extracted.trim().length<50){setImportError("This looks like a scanned image or unreadable. Please paste your CV text below");return;}setImportParsed(parseCVText(extracted));void logCvImport();}catch(error){setImportError("This looks like a scanned image or unreadable. Please paste your CV text below");setNotice(error instanceof Error?error.message:"Could not extract this file. You can paste the CV text instead.");}finally{setImportBusy(false);}}
 function parsePastedCv(){if(pasteCvText.trim().length<50){setImportError("Please paste at least 50 characters of CV text.");return;}const parsed=parseCVText(pasteCvText);setRawCvText(pasteCvText);setImportParsed(parsed);setImportError("");logCvImport();}
 function saveLocalCv(){const data=currentCvData(),now=new Date().toISOString(),id=localCvId?Number(localCvId):Date.now();const item:LocalSavedCv={id,fullName:name||"Untitled CV",jobTitle:title||role||"Professional CV",targetRole,lastEdited:now,data};try{const next=[item,...savedCvs.filter(v=>v.id!==id)];localStorage.setItem("usekit_saved_cvs",JSON.stringify(next));setSavedCvs(next);setLocalCvId(String(id));return true;}catch{setNotice("Your CV could not be saved in this browser. Storage may be full; download your PDF to keep a copy.");return false;}}
 function editLocalCv(item:LocalSavedCv){applyCvData(item.data);setTargetRole(item.targetRole||"");setLocalCvId(String(item.id));setStep(0);setNotice("Saved CV loaded. Your edits will update this saved copy.");window.scrollTo({top:0,behavior:"smooth"});}
 function deleteLocalCv(id:number){if(!window.confirm("Delete this saved CV?"))return;const next=savedCvs.filter(item=>item.id!==id);try{localStorage.setItem("usekit_saved_cvs",JSON.stringify(next));setSavedCvs(next);if(localCvId===String(id))setLocalCvId("");setNotice("Saved CV deleted from this device.");}catch{setNotice("Could not update saved CVs on this device.");}}
 function rewriteAbout(){const target=targetRole.trim();if(target.length<3)return;const basis=summary.trim()||[role,title,skills,work.map(x=>[x.role,x.company].filter(Boolean).join(" at ")).filter(Boolean).join(", ")].filter(Boolean).join("; "),yearsText=years.trim()?years.trim()+" of experience":"",key=target.toLowerCase().replace(/[^a-z]/g,"_"),aboutTemplates:Record<string,string>={customer_support:"Customer Support professional",teacher:"Education professional",developer:"Software Developer",marketing:"Marketing professional",sales:"Sales professional",default:"Motivated professional"};const templateKey=Object.keys(aboutTemplates).find(k=>k!=="default"&&key.includes(k))||"default";const opening=aboutTemplates[templateKey];const verified=yearsText?" with "+yearsText:"";const evidence=basis||"[Add your relevant experience, skills and strengths]";setSummaryOptions([opening+verified+". Background includes "+evidence+". Interested in applying this experience to "+target+" opportunities.", "Professional profile for "+target+": "+evidence+". Focused on clear communication, reliable delivery and continued professional development."]);}
 function chooseSummary(value:string){setSummary(value);setSummaryOptions([]);}
 function rewriteWorkDetails(item:Work,index:number){const lines=item.details.split(/\n+/).map(v=>v.trim()).filter(Boolean);if(!lines.length)return;const verbs=["Managed","Improved","Delivered","Supported","Coordinated","Contributed to"];const cleaned=lines.map(line=>line.replace(/^[-•*]\s*/,""));const first=cleaned.map((line,i)=>verbs[(index+i)%verbs.length]+" "+line.charAt(0).toLowerCase()+line.slice(1).replace(/[.!?]+$/,"")+".").join("\n");const second=cleaned.map(line=>"Responsible for "+line.charAt(0).toLowerCase()+line.slice(1).replace(/[.!?]+$/,"")+".").join("\n");setWorkSuggestions(v=>({...v,[item.id]:[first,second]}));setNotice("Choose a draft only if its wording accurately describes your original responsibilities. Your existing text has not been changed.");}function applyWorkSuggestion(id:number,value:string){updateWork(id,"details",value);setWorkSuggestions(v=>({...v,[id]:[]}));}
 const roleSkillSuggestions:Record<string,string[]>={customer:["Customer communication","Complaint resolution","CRM systems","Service recovery","Call handling","Case documentation"],teacher:["Lesson planning","Classroom management","Student assessment","Curriculum delivery","Learning support"],developer:["JavaScript","TypeScript","React","API integration","Git","Debugging"],marketing:["Content strategy","Campaign coordination","SEO","Market research","Social media"],sales:["Lead generation","Client relationship management","Negotiation","Sales reporting","CRM"],accounting:["Financial reporting","Reconciliation","Accounts payable","Excel","Tax documentation"],admin:["Records management","Scheduling","Office coordination","Customer service"]};
 const roleSkillKey=Object.keys(roleSkillSuggestions).find(key=>targetRole.toLowerCase().includes(key))||"";
 const suggestedRoleSkills=roleSkillSuggestions[roleSkillKey]||[];
 function addSuggestedSkill(skill:string){setSkills(v=>[...new Set([...v.split(/[,;\n]/).map(x=>x.trim()).filter(Boolean),skill])].join(", "));}
 function autoWriteCustom(section:CvCustomSection){const titleKey=section.title.toLowerCase();let prompts:string[]=[];if(titleKey.includes("cert"))prompts=["Add certification name · issuing organisation · year · credential ID (if applicable).","List only qualifications you have earned, with the exact title and date."];else if(titleKey.includes("language"))prompts=["Add each language and your actual proficiency (e.g. fluent, professional, conversational).","List languages you can genuinely use and describe your level accurately."];else if(titleKey.includes("award"))prompts=["Add award or recognition · awarding body · year · reason for recognition.","Describe the achievement and include a verifiable date or result."];else if(titleKey.includes("volunteer"))prompts=["Add organisation · volunteer role · dates · responsibilities.","Describe the community activity and what you personally contributed."];else if(titleKey.includes("hobb"))prompts=["Add relevant interests that demonstrate skills or sustained involvement.","List genuine interests that you are comfortable discussing in an interview."];else if(titleKey.includes("reference"))prompts=["References available on request.","Add a referee only after obtaining their permission to share their contact details."];else if(titleKey.includes("nysc"))prompts=["Add NYSC PPA · role · location · service dates · responsibilities.","Describe your actual NYSC assignment and contributions; do not include invented duties."];else prompts=["Add relevant details, dates, organisation and your specific contribution.","Use factual information you can verify; leave unknown details blank."];setCustomSuggestions(v=>({...v,[section.id]:prompts}));}
 function addCustomSection(title:string){const clean=title.trim().replace(/^add\s+/i,"");if(!clean)return;const section={id:Date.now(),title:clean,content:""};setCustomSections(v=>[...v,section]);setCustomTitle("");setCustomModalOpen(false);return section.id;}
 function updateCustomSection(id:number,key:"title"|"content",value:string){setCustomSections(v=>v.map(x=>x.id===id?{...x,[key]:value}:x));}
 function startCvSpeech(){const w=window as unknown as {SpeechRecognition?:new()=>{lang:string;interimResults:boolean;onresult?:(event:{results:ArrayLike<ArrayLike<{transcript:string}>>})=>void;onerror?:()=>void;start:()=>void},webkitSpeechRecognition?:new()=>{lang:string;interimResults:boolean;onresult?:(event:{results:ArrayLike<ArrayLike<{transcript:string}>>})=>void;onerror?:()=>void;start:()=>void}};const Recognition=w.SpeechRecognition||w.webkitSpeechRecognition;if(!Recognition)return;const recognition=new Recognition();recognition.lang="en-NG";recognition.interimResults=false;recognition.onresult=event=>{const title=event.results?.[0]?.[0]?.transcript.replace(/^add\s+/i,"").trim();if(title){const id=addCustomSection(title);if(id)autoWriteCustom({id,title,content:""});}};recognition.onerror=()=>setNotice("Voice input was not available. You can type the custom field name instead.");recognition.start();}
 useEffect(()=>{try{const raw=localStorage.getItem("usekit_saved_cvs");if(raw){const parsed=JSON.parse(raw);if(Array.isArray(parsed))setSavedCvs(parsed.filter(x=>x&&typeof x.id==="number"&&x.data&&typeof x.data==="object"));}}catch{setNotice("Saved CVs could not be read. Your existing CV draft remains available.");}},[]);
