 async function payToRemoveWatermark(){if(!email.trim()){setNotice("Add your email address in Contact before paying to remove the watermark.");setStep(1);return;}saveDraft();setPaymentLoading(true);try{const response=await fetch("/api/payments/initialize",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email,purpose:"cv_watermark"})});const data=await response.json();if(!response.ok||!data.authorizationUrl)throw new Error(data.error||"Could not start payment.");window.location.assign(data.authorizationUrl);}catch(e){setNotice(e instanceof Error?e.message:"Could not start payment.");setPaymentLoading(false);}}
 const steps=["Profile","Contact","Experience","Education","Skills","Projects & review"];const roleKey=useMemo(()=>{const key=role.toLowerCase()+" "+title.toLowerCase();return Object.keys(roleSkills).find(k=>key.includes(k))||""},[role,title]);const suggested=useMemo(()=>roleSkills[roleKey]||["Communication","Problem Solving","Teamwork","Time Management","Attention to Detail"],[roleKey]);const suggestedTools=useMemo(()=>roleTools[roleKey]||[],[roleKey]);const workPrompts=useMemo(()=>rolePrompts[roleKey]||["Supported [task or process] by coordinating [specific activity].","Improved [workflow] through [action taken].","Prepared [reports or records] to support [team or outcome]."],[roleKey]);const atsKeywords=useMemo(()=>{const stop=new Set(["about","after","also","and","are","based","been","being","both","business","candidate","company","could","development","different","each","from","have","including","into","must","other","over","role","should","skills","strong","their","them","then","this","through","under","using","various","what","when","where","which","will","with","within","years","your"]);const source=job.toLowerCase().match(/[a-z][a-z0-9+#.-]{2,}/g)||[];const words=[...new Set(source)].filter(w=>!stop.has(w));const cvText=[role,title,summary,skills,tools,soft,experienceText(work),projects,certifications].join(" ").toLowerCase();return {matched:words.filter(w=>cvText.includes(w)),missing:words.filter(w=>!cvText.includes(w)).slice(0,18),total:words.length}},[job,role,title,summary,skills,tools,soft,work,projects,certifications]);
