 function downloadModern(){const d=new jsPDF();let y=23,page=1;const side=74,main=87;const drawSidebar=()=>{d.setFillColor(44,62,80);d.rect(0,0,side,297,"F");d.setTextColor(245,248,240);d.setFont("helvetica","bold");d.setFontSize(9);d.text("CONTACT",12,23);d.setFont("helvetica","normal");d.setFontSize(8);let sy=31;for(const v of [email,phone,location,website,linkedin,behance].filter(Boolean)){const lines=d.splitTextToSize(v,side-24);d.text(lines,12,sy);sy+=lines.length*4+4;}const sideSec=(title:string,body:string)=>{if(!body.trim())return;sy+=7;d.setFont("helvetica","bold");d.setFontSize(9);d.text(title.toUpperCase(),12,sy);sy+=6;d.setFont("helvetica","normal");d.setFontSize(7.5);for(const line of d.splitTextToSize(body,side-24)){if(sy>282){d.addPage();d.setFillColor(44,62,80);d.rect(0,0,side,297,"F");d.setTextColor(245,248,240);sy=20;}d.text(line,12,sy);sy+=4;}};sideSec("Skills",skills);sideSec("Tools",tools);sideSec("Education",education.map(x=>[x.qualification,x.school,x.year].filter(Boolean).join(" · ")).join("\n"));sideSec("Languages",languages);sideSec("Soft skills",soft);sideSec("References",reference);};const mainSection=(title:string,body:string)=>{if(!body.trim())return;y+=9;d.setTextColor(33,20,15);d.setFont("helvetica","bold");d.setFontSize(10);d.text(title.toUpperCase(),main,y);y+=6;d.setDrawColor(243,107,33);d.line(main,y,195,y);y+=7;d.setFont("helvetica","normal");d.setFontSize(10);for(const line of d.splitTextToSize(body,108)){if(y>278){d.setFontSize(7);d.setTextColor(150);if(!watermarkUnlocked)d.text("Made with UseKit",main,288);d.addPage();page++;d.setFillColor(33,20,15);d.rect(0,0,side,297,"F");d.setTextColor(245,248,240);y=22;}d.setTextColor(65,55,49);d.text(line,main,y);y+=4.5;}};drawSidebar();d.setTextColor(33,25,21);d.setFont("helvetica","bold");d.setFontSize(21);d.text(name||"YOUR NAME",main,25);d.setFont("helvetica","normal");d.setFontSize(10);d.setTextColor(118,107,101);d.text(title||role||"Professional title",main,33);y=46;mainSection("Career Objective",careerObjective);mainSection("Professional Summary",summary);mainSection("Work Experience",work.map(x=>[x.role+" | "+x.company,x.location,[x.start,x.end].filter(Boolean).join(" – "),x.details].filter(Boolean).join("\n")).join("\n\n"));mainSection("Featured Projects",projects);mainSection("Certifications",certifications);customSections.filter(section=>!(section.title.toLowerCase().includes("language")&&section.content.trim()===languages.trim())&&!(section.title.toLowerCase().includes("cert")&&section.content.trim()===certifications.trim())).forEach(section=>mainSection(section.title,section.content));for(let p=1;p<=d.getNumberOfPages();p++){d.setPage(p);d.setFontSize(7);d.setTextColor(150);if(!watermarkUnlocked)d.text("Made with UseKit",main,288);}d.save((name.trim().replace(/\s+/g,"_")||"Your_Name")+"_CV.pdf");void logToolUse("cv_generator");}
function downloadExecutive(){const d=new jsPDF();let y=48;d.setFillColor(35,39,47);d.rect(0,0,210,42,"F");d.setFillColor(233,43,80);d.rect(0,42,210,2,"F");d.setTextColor(255,255,255);d.setFont("helvetica","bold");d.setFontSize(24);d.text(name||"YOUR NAME",20,19);d.setFont("helvetica","normal");d.setFontSize(10);d.text(title||role||"Professional title",20,28);d.setFontSize(8);d.text([email,phone,location,website,linkedin].filter(Boolean).join("  |  "),20,36,{maxWidth:170});const section=(heading:string,body:string)=>{if(!body.trim())return;y+=8;if(y>268){d.addPage();y=20;}d.setTextColor(233,43,80);d.setFont("helvetica","bold");d.setFontSize(10);d.text(heading.toUpperCase(),20,y);y+=5;d.setDrawColor(220,220,224);d.line(20,y,190,y);y+=6;d.setTextColor(48,50,56);d.setFont("helvetica","normal");d.setFontSize(9.5);for(const line of d.splitTextToSize(body,170)){if(y>278){d.addPage();y=20;}d.text(line,20,y);y+=4.5;}};section("Executive Profile",profileText||summary);section("Career Objective",careerObjective);section("Professional Experience",work.map(x=>[x.role+" · "+x.company,x.location,[x.start,x.end].filter(Boolean).join(" – "),x.details].filter(Boolean).join("\n")).join("\n\n"));section("Education",education.map(x=>[x.qualification,x.school,x.year].filter(Boolean).join(" · ")).join("\n"));section("Core Skills",skills);section("Tools & Technologies",tools);section("Selected Projects",projects);section("Certifications",certifications);section("Languages",languages);section("Additional Information",customSections.filter(x=>x.title.trim()&&x.content.trim()).map(x=>x.title+"\n"+x.content).join("\n\n"));for(let p=1;p<=d.getNumberOfPages();p++){d.setPage(p);d.setFontSize(7);d.setTextColor(150);if(!watermarkUnlocked)d.text("Made with UseKit",160,288);}d.save((name.trim().replace(/\s+/g,"_")||"Your_Name")+"_Executive_CV.pdf");void logToolUse("cv_generator");}
